{"implementation":"import math


def solve(case):
    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "core_distance" not in case or "distances" not in case:
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("every node identifier must be a string")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")

    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if set(core_distance) != set(nodes):
        raise ValueError("core_distance keys must exactly match nodes")
    for node in nodes:
        value = core_distance[node]
        if not is_number(value) or value < 0:
            raise ValueError("core distances must be finite non-negative numbers")

    if not isinstance(distances, list):
        raise ValueError("distances must be an array")

    node_set = set(nodes)
    seen_pairs = set()
    edges = []
    for entry in distances:
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError("each distance must be a three-element array")
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set:
            raise ValueError("distance endpoint is not present in nodes")
        if left == right:
            raise ValueError("self-distances are not valid edges")
        if not is_number(distance) or distance < 0:
            raise ValueError("distances must be finite non-negative numbers")

        first, second = (left, right) if left < right else (right, left)
        pair = (first, second)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance edge")
        seen_pairs.add(pair)

        reachability = max(core_distance[first], core_distance[second], distance)
        edges.append((reachability, first, second))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    selected = []
    for weight, first, second in edges:
        root_first = find(first)
        root_second = find(second)
        if root_first == root_second:
            continue
        if root_first < root_second:
            parent[root_second] = root_first
        else:
            parent[root_first] = root_second
        selected.append([first, second, weight])
        if len(selected) == len(nodes) - 1:
            break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    return {
        "mst_edges": selected,
        "total_weight": sum(edge[2] for edge in selected),
    }
"}
